        static string Hash(byte[] b){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(b)).Replace("-","");}
        internal static string Digest(PracticeMixedMovementState s)
        {
            using(var memory=new MemoryStream())using(var w=new BinaryWriter(memory))
            {
                foreach(var b in s.SnapshotForComparison())w.Write(b);w.Write(s.CopyTerrainPool());w.Write(s.CallerWordAfter);w.Write(s.UiRequests);w.Write(unchecked((short)s.SelectedWaypoint));w.Write(unchecked((short)s.Schedule.BatchStart));w.Write(s.Schedule.CompletedCycles);w.Write(unchecked((short)s.MovieCounter));w.Write(s.RandomState);w.Flush();return Hash(memory.ToArray());
            }
        }
        internal static void Run(Action<string,Action> check,Action<string,Action> evidence,string assets)
        {
            string programs=Path.Combine(Path.GetDirectoryName(assets),"Programs");PracticeMapStartup startup=null;Action prepare=delegate{if(startup==null)startup=PracticeMapStartup.CreateBssb202(programs,File.ReadAllBytes(Path.Combine(assets,"Graphics","BSSB202.SCN")),731);};
            Func<int,PracticeMixedMovementState> create=delegate(int p){prepare();return PracticeMixedMovementState.Create(programs,startup,p);};
            check("Mixed moving fleets match679 original-only1016 complete-state and scalar digests",delegate{
                int frames=0,shipMoves=0,airMoves=0,wraps=0;Need(goldens.Length==7,"Seven original1012R2 profiles");for(int h=0;h<7;h++){var s=create(h);Need(goldens[h].Length==97&&Digest(s)==goldens[h][0],"Original mixed map-built initial "+h);for(int n=1;n<=96;n++){var before=s;string frozen=Digest(s);s=s.Advance();Need(Digest(s)==goldens[h][n],"Original mixed complete moving state "+h+"/"+n);Need(Digest(before)==frozen,"Original mixed caller immutability");frames++;}Need(!s.CanAdvance&&s.Visits==96,"Compared moving limit");shipMoves+=s.TotalShipMoves;airMoves+=s.TotalAircraftMoves;wraps+=s.SchedulerWraps;}Need(frames==672&&shipMoves==25&&airMoves==12&&wraps==21,"Original source movement/scheduler coverage");
            });
            check("Mixed moving arrival clears selected249shared flag at source poll64 and carries the clear",delegate{
                var s=create(6);Need(s.SelectedFleetFlag==109,"Supplied diagnostic6D marker");for(int n=0;n<63;n++)s=s.Advance();Need(s.Visits==63&&s.SelectedFleetFlag==109&&BitConverter.ToInt16(s.CopyFleetPool(),16*492+12)==110&&BitConverter.ToInt32(s.Backing.CopyTaskRecord(16),304)==0,"Source boundary before arrivalconsume");s=s.Advance();Need(s.Visits==64&&s.SelectedFleetFlag==0&&s.MovementChangedSharedBacking&&s.SelectedWaypoint==4&&s.Schedule.BatchStart==24&&s.Schedule.CompletedCycles==2,"Source selectedother writeback at64");s=s.Advance();Need(s.SelectedFleetFlag==0&&!s.MovementChangedSharedBacking&&Digest(s)==goldens[6][65],"Clear must carry into nextprephase without repeat");
            });
            check("Mixed moving scheduler-before-policy counterfactual differs from all seven original first polls",delegate{
                for(int h=0;h<7;h++){var s=create(h);string frozen=Digest(s);Need(Digest(s.Advance())==goldens[h][1]&&Digest(s.AdvanceWithReversedOrderForComparison())!=goldens[h][1],"Source callbackorder mutation "+h);Need(Digest(s)==frozen,"Counterfactual copied input");}
            });
            check("Mixed moving copies reset profile bounds and exhausted window preserve caller state",delegate{
                var s=create(2);string frozen=Digest(s);foreach(var b in new[]{s.CopyShipPool(),s.CopyFleetPool(),s.CopyPrimaryOrders(),s.CopyCandidateRegion(),s.CopyTerrainPool(),s.CopyScoreRegion(),s.CopyEffectPool(),s.Backing.CopyRegion(),s.Grid.CopyCells()})b[0]^=255;Need(Digest(s)==frozen&&Digest(create(2))==frozen,"Moving owned snapshots/reset");bool rejected=false;try{create(7);}catch(ArgumentOutOfRangeException){rejected=true;}Need(rejected,"Moving invalidprofile");while(s.CanAdvance)s=s.Advance();frozen=Digest(s);rejected=false;try{s.Advance();}catch(InvalidOperationException){rejected=true;}Need(rejected&&Digest(s)==frozen,"Moving exhaustedwindow transactional");
            });
            check("Separate moving comparison retains eight-visit policy-only mode and old input limits",delegate{
                prepare();var old=PracticeMixedNavigationState.Create(programs,startup,0);string frozen=PracticeMixedNavigationChecks.Digest(old);var moving=create(6);moving=moving.Advance();Need(PracticeMixedNavigationState.Presets.Count==6&&PracticeMixedNavigationState.MaximumVisits==8&&old.WindowVisits==8&&PracticeMixedMovementState.Presets.Count==7&&moving.WindowVisits==96&&PracticeMixedNavigationChecks.Digest(old)==frozen,"Existing eightvisit API retained");bool rejected=false;try{PracticeMixedNavigationState.Create(programs,startup,6);}catch(ArgumentOutOfRangeException){rejected=true;}Need(rejected,"Shortmovingfixture must not broaden oldprofile entry");
            });
            evidence("Mixed moving fleets match all672 original1012R2 full eight-pool records and scheduler scalars",delegate{Full(Path.Combine(Path.GetDirectoryName(assets),"Evidence","Mixed-Movement-1012.bin"),create);});
        }
