        static byte[] Patch(BinaryReader r,byte[] basis){int count=r.ReadInt32(),last=-1;Need(count>=0&&count<=basis.Length,"Moving fixture patchcount");var b=(byte[])basis.Clone();for(int n=0;n<count;n++){int at=r.ReadInt32();Need(at>last&&at<b.Length,"Moving fixture patchbounds");last=at;b[at]=r.ReadByte();}return b;}
