                for(;;){int id=r.ReadInt32();if(id==-1)break;int h=r.ReadInt32(),frame=r.ReadInt32(),parent=r.ReadInt32(),child=r.ReadInt32();uint scratch=r.ReadUInt32(),ui=r.ReadUInt32();short point=r.ReadInt16(),cursorBefore=r.ReadInt16();uint cycleBefore=r.ReadUInt32();short cursorAfter=r.ReadInt16();uint cycleAfter=r.ReadUInt32();short movie=r.ReadInt16();uint random=r.ReadUInt32(),notify=r.ReadUInt32();var terrain=Patch(r,zeroT);var before=new byte[8][];var after=new byte[8][];for(int n=0;n<8;n++){before[n]=Patch(r,bases[n]);after[n]=Patch(r,before[n]);}Need(id==count&&h==id/96&&frame==id%96&&notify==0,"Original moving metadata");if(frame==0)s=create(h);Need(s.ParentFleet==parent&&s.AircraftFleet==child&&s.Schedule.BatchStart==cursorBefore&&s.Schedule.CompletedCycles==cycleBefore&&Hash(s.CopyTerrainPool())==Hash(terrain),"Original moving inputmetadata");var actual=s.SnapshotForComparison();for(int n=0;n<8;n++)Need(Hash(actual[n])==Hash(before[n]),"Original moving independently prepared/carried fullinput "+id+"/"+n);s=s.Advance();actual=s.SnapshotForComparison();for(int n=0;n<8;n++)Need(Hash(actual[n])==Hash(after[n]),"Original moving fulloutput "+id+"/"+n);Need(s.Schedule.BatchStart==cursorAfter&&s.Schedule.CompletedCycles==cycleAfter&&unchecked((uint)s.CallerWordAfter)==scratch&&s.UiRequests==ui&&s.SelectedWaypoint==point&&s.MovieCounter==movie&&s.RandomState==random,"Original moving outputscalars");count++;}
